/* Cryo geometry follows the authoritative beam aperture and real cold state.
 * Draw calls use no RNG and do not advance a simulation or cosmetic timer. */
static void ice_face83(const float*p,SDL_FColor c){int first=nquad;quad(0,0,1,1,c,.5f,.5f,0,0);if(nquad==first)return;for(int i=0;i<4;i++){vertices[first*4+i].position=(SDL_FPoint){p[i*2]*3,p[i*2+1]*3};vertices[first*4+i].tex_coord=(SDL_FPoint){.5f,.5f};}}
static void ice_shard83(float x,float y,float size,float angle,float alpha){float dx=cosf(angle)*size,dy=sinf(angle)*size;float points[8]={x+dx,y+dy,x-dy*.42f,y+dx*.42f,x-dx,y-dy,x+dy*.42f,y-dx*.42f};ice_face83(points,(SDL_FColor){.48f,.88f,1,alpha});beam_ribbon(x-dx,y-dy,x+dx,y+dy,.16f,(SDL_FColor){.88f,.98f,1,alpha});}
static void cryo_stream83(float x,float y,float xx,float yy,float width,float intensity,int seed){float dx=xx-x,dy=yy-y,len=hypotf(dx,dy);if(len<1)return;dx/=len;dy/=len;float nx=-dy,ny=dx,phase=reducedMotion?0:fmodf(g.tick*4.f+seed*7,13.f);beam_ribbon(x,y,xx,yy,width*1.2f,(SDL_FColor){.12f,.65f,1,.11f*intensity});beam_ribbon(x,y,xx,yy,fmaxf(.4f,width*.20f),(SDL_FColor){.56f,.92f,1,.28f*intensity});int lanes=width>8?3:width>4?2:1;for(int lane=0;lane<lanes;lane++)for(float at=phase+lane*5;at<len;at+=13){float spread=lanes==1?0:((lane+.5f)/lanes*2-1)*width*.72f,wobble=reducedMotion?0:sinf(at*.13f+lane*2+seed)*width*.12f,cross=spread+wobble;ice_shard83(x+dx*at+nx*cross,y+dy*at+ny*cross,fminf(4,1.7f+width*.15f),atan2f(dy,dx),.68f*intensity);}light(xx,yy,width+2,.36f,.84f,1,.22f*intensity);}
static void ice_shell83(float x,float y,float rx,float ry,const Ice83*s,int boss){if(!s->frozen&&!s->charge)return;float cold=s->frozen?1:fminf(1,s->charge/(boss?600.f:300.f)),fade=s->frozen?fminf(1,s->frozen/10.f):1;rx=fmaxf(7,rx);ry=fmaxf(8,ry);if(boss){for(int k=0;k<8;k++){float a=k*PI/4,b=a+PI/7;beam_ribbon(x+cosf(a)*rx,y+sinf(a)*ry,x+cosf(b)*rx,y+sinf(b)*ry,.65f,(SDL_FColor){.5f,.88f,1,cold*.8f*fade});}return;}float px[8]={x-rx*.6f,x+rx*.6f,x+rx,x+rx,x+rx*.6f,x-rx*.6f,x-rx,x-rx},py[8]={y-ry,y-ry,y-ry*.55f,y+ry*.55f,y+ry,y+ry,y+ry*.55f,y-ry*.55f};for(int i=0;i<8;i++){int j=(i+1)&7;float face[8]={x,y,px[i],py[i],px[j],py[j],x,y};ice_face83(face,(SDL_FColor){.22f,.65f,.92f,cold*fade*(i&1?.08f:.14f)});beam_ribbon(px[i],py[i],px[j],py[j],s->frozen?.48f:.22f,(SDL_FColor){.55f,.9f,1,cold*.85f*fade});}if(s->frozen){beam_ribbon(x-rx*.6f,y-ry,x+rx*.6f,y+ry,.25f,(SDL_FColor){.8f,.98f,1,.38f*fade});int cracks=s->shell?clamp(s->fracture*4/s->shell,0,3):0;for(int k=0;k<cracks;k++){float a=1+k*2.1f;beam_ribbon(x,y,x+cosf(a)*rx*.8f,y+sinf(a)*ry*.8f,.38f,(SDL_FColor){.04f,.21f,.4f,.85f*fade});beam_ribbon(x+cosf(a)*rx*.35f,y+sinf(a)*ry*.35f,x+cosf(a+.8f)*rx*.65f,y+sinf(a+.8f)*ry*.65f,.22f,(SDL_FColor){.8f,.97f,1,.7f*fade});}}}
static int renderedIceShells83,renderedIceShards83;
static void draw_ice_shells83(void){renderedIceShells83=0;if(g.mode!=1||ex.travel||ex.intro)return;nquad=0;for(int i=0;i<MAXE;i++){Obj*o=g.enemies+i;if(!o->on||o->hp<=0||(!o->ice83.frozen&&!o->ice83.charge))continue;float r=pc_enemy_radius(o)+3;ice_shell83(o->x/(float)Q,o->y/(float)Q,r,r*.85f,&o->ice83,o->type==4);renderedIceShells83++;}for(int i=0;i<32;i++){EnvironmentHazard*h=ex.env.hazards+i;if(!h->on||(!h->ice83.frozen&&!h->ice83.charge))continue;ice_shell83(h->x/(float)Q,h->y/(float)Q,h->r+3,h->r+3,&h->ice83,0);renderedIceShells83++;}Giant*b=&ex.giant;if(b->active)for(int i=0;i<9;i++){GiantPart*p=b->parts+i;if(!p->hp||!p->visible)continue;Ice83 state=p->ice83;state.frozen=b->ice83.frozen;if(!state.frozen&&!state.charge)continue;ice_shell83(p->x,p->y,p->w*.55f,p->h*.55f,&state,1);renderedIceShells83++;}flush(halo);}
static void draw_ice_shards83(void){renderedIceShards83=0;if(g.mode!=1||ex.travel||ex.intro)return;int limit=reducedMotion?32:96;for(int i=0;i<96&&renderedIceShards83<limit;i++){IceShard83*p=iceShards83+i;float age=(g.tick-p->tick)/50.f,life=p->kind==2?.8f:.45f;if(!p->kind||p->wave!=g.wave||p->section!=ex.section||age<0||age>=life)continue;float t=age/life;ice_shard83(p->x+p->vx*age,p->y+p->vy*age+age*age*12,p->size*(1-t*.4f),p->spin*(reducedMotion?0:age),.85f*(1-t));renderedIceShards83++;}}
